function normalizarCiudad(s) {
  return String(s || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

// Devuelve { lat, lon } de una ciudad (texto libre) o null si no se reconoce.
function geocodificarCiudad(ciudad) {
  if (!ciudad) return null;
  const c = COORDS[normalizarCiudad(ciudad)];
  return c ? { lat: c[0], lon: c[1] } : null;
}

module.exports = { normalizarCiudad, geocodificarCiudad };
